-- ViCare texts for the release build: free on-device translation of what was
-- actually said is a released feature (no longer "coming soon"), and the
-- interpreter has 3,700+ sentences in 20 packs. Same ViCare rows as 0019
-- (0019 was edited to match), for databases that already applied 0019.
-- Idempotent. Mirrors src/lib/seed.ts.
PRAGMA foreign_keys = ON;

UPDATE product_translations
SET name = 'ViCare – Đi khám bệnh ở Nhật',
    tagline = 'App miễn phí giúp người Việt đi khám bệnh ở Nhật: phiên dịch khi khám, hồ sơ y tế, đọc giấy tờ và túi thuốc',
    description = 'ViCare là app miễn phí, phi lợi nhuận của ViMai, đồng hành cùng người Việt tại Nhật từ lúc thấy trong người không ổn đến lúc cầm túi thuốc về nhà. Phiên dịch khi khám với hơn 3.700 mẫu câu bác sĩ, nhân viên và bệnh nhân trong 20 gói theo khoa và tình huống (nội, nhi, sản phụ khoa, mắt, tai mũi họng, nha, da liễu, nhà thuốc, cấp cứu…), nghe qua micro bằng nhận dạng giọng nói của điện thoại. Hồ sơ y tế trên điện thoại: thông tin khẩn cấp hiện bằng tiếng Nhật, nhật ký khám kèm chi phí và tổng theo năm cho 医療費控除, thuốc đang uống, nhắc uống thuốc và tái khám. Chụp túi thuốc, phiếu hẹn, hoá đơn, kết quả xét nghiệm, kết quả khám sức khoẻ, phiếu khai bệnh và giấy đồng ý để đọc ngay trên máy. “Tôi bị ốm” gợi ý nên khám khoa nào từ 100 triệu chứng và 58 dấu hiệu nguy hiểm; danh sách hơn 140.000 cơ sở y tế ở 47 tỉnh từ dữ liệu mở của Bộ Y tế Nhật. Kèm 2.069 câu giao tiếp, cẩm nang 174 bệnh, 70 bài thủ tục và bảo hiểm, từ điển y khoa 2.669 từ. Không cần tài khoản; dữ liệu cá nhân chỉ lưu trên điện thoại.',
    long_description = 'Thông tin tham khảo và công cụ hỗ trợ giao tiếp khi đi khám, không phải chẩn đoán và không thay thế lời khuyên của bác sĩ hay dược sĩ. Nội dung do đội ViCare biên soạn từ nguồn y tế công khai của Nhật và kiểm tra. Không cần tài khoản, không quảng cáo; dữ liệu cá nhân chỉ lưu trên điện thoại.',
    target_audience = 'Người Việt sống tại Nhật cần đi khám bệnh, và gia đình, công ty, trường học, nghiệp đoàn hỗ trợ họ.',
    features = '["Phiên dịch khi khám: hơn 3.700 mẫu câu bác sĩ – bệnh nhân trong 20 gói theo khoa và tình huống, nghe qua micro; bệnh nhân nói hoặc gõ tiếng Việt, bác sĩ đọc tiếng Nhật", "Hồ sơ y tế: thông tin khẩn cấp bằng tiếng Nhật (dị ứng, bệnh nền, nhóm máu, người liên hệ), nhật ký khám, thuốc đang uống", "Đọc giấy tờ bằng camera ngay trên máy: túi thuốc ra lịch uống, phiếu hẹn, hoá đơn, xét nghiệm, khám sức khoẻ, phiếu khai bệnh", "Dịch đúng lời người nói, kể cả câu không có trong kho mẫu: miễn phí, chạy ngay trên điện thoại, dùng được khi không có mạng sau khi tải gói ngôn ngữ lần đầu (ghi rõ “Dịch máy”, kèm câu dịch ngược để kiểm tra; trên app iPhone/Android)", "Tôi bị ốm: 100 triệu chứng, 15 vùng cơ thể, 58 dấu hiệu nguy hiểm, gợi ý nên khám khoa nào", "Tìm nơi khám: hơn 140.000 cơ sở y tế ở 47 tỉnh (dữ liệu mở của Bộ Y tế Nhật), lọc theo 20 khoa, kèm tìm trên Google Maps", "Khẩn cấp 119 · 110 · #7119 · #8000: câu nói tiếng Nhật, tự điền địa chỉ đã lưu", "Nhật ký khám có chi phí phòng khám và nhà thuốc, tổng theo năm cho 医療費控除; nhắc uống thuốc, nhắc tái khám; xuất CSV, sao lưu", "2.069 câu giao tiếp (19 tình huống), cẩm nang 174 bệnh, 70 bài thủ tục và bảo hiểm, từ điển y khoa 2.669 từ, có furigana", "Miễn phí, phi lợi nhuận, không quảng cáo, không cần tài khoản; giao diện tiếng Việt, tiếng Nhật, tiếng Anh"]',
    seo_title = 'ViCare – App đi khám bệnh ở Nhật cho người Việt (miễn phí)',
    seo_description = 'ViCare giúp người Việt đi khám bệnh ở Nhật: phiên dịch khi khám hơn 3.700 mẫu câu, hồ sơ y tế, đọc túi thuốc bằng camera, nên khám khoa nào, gọi 119. Miễn phí.'
WHERE locale = 'vi'
  AND product_id = (SELECT id FROM products WHERE slug = 'vicare');

UPDATE product_translations
SET name = 'ViCare: See a Doctor in Japan',
    tagline = 'A free app for Vietnamese people seeing a doctor in Japan: visit interpreter, health records, camera reading of papers and medicine bags',
    description = 'ViCare is a free, non-profit ViMai app that supports Vietnamese people in Japan from the moment they feel unwell until they bring their medicine home. The doctor-visit interpreter has over 3,700 doctor, staff and patient sentences in 20 packs by department and situation (internal medicine, paediatrics, obstetrics and gynaecology, eyes, ENT, dentistry, dermatology, pharmacy, emergency and more) and listens through the phone''s own speech recognition. Health records stay on the phone: emergency information shown in Japanese, a visit diary with costs and yearly totals for 医療費控除 (the medical expense deduction), current medicines, and medicine and follow-up reminders. Photograph a medicine bag, appointment slip, receipt, test result, health check result, questionnaire or consent form and it is read on the phone. “I feel sick” suggests a department from 100 symptoms and 58 warning signs, and a list of over 140,000 medical facilities in all 47 prefectures comes from the Ministry of Health''s open data. It also has 2,069 phrases, a guide to 174 illnesses, 70 articles on procedures and insurance, and a 2,669-word medical dictionary. No account; personal data stays on your phone.',
    long_description = 'Reference information and a communication aid for doctor visits; it is not a diagnosis and does not replace a doctor''s or pharmacist''s advice. Content is written by the ViCare team from public Japanese health sources and checked. No account and no ads; personal data stays on your phone.',
    target_audience = 'Vietnamese people living in Japan who need to see a doctor, and the family, employers, schools and support organisations who help them.',
    features = '["Visit interpreter: over 3,700 doctor–patient sentences in 20 department and situation packs, by microphone; the patient speaks or types Vietnamese, the doctor reads Japanese", "Health records: emergency information in Japanese (allergies, conditions, blood type, contact), visit diary, current medicines", "Camera reading on the phone: medicine bags into a dosing schedule, appointment slips, receipts, test and health check results, questionnaires", "Translates what was actually said, even sentences that are not stored: free, on the phone, and offline after a one-time language download (labelled “machine translation”, with a back-translation to check; iPhone/Android app)", "I feel sick: 100 symptoms, 15 body areas, 58 warning signs, and which department to visit", "Find a clinic: over 140,000 medical facilities in 47 prefectures (Ministry of Health open data), 20 departments, plus Google Maps search", "Emergency 119 · 110 · #7119 · #8000: Japanese scripts with your saved address filled in", "Visit diary with clinic and pharmacy costs and yearly totals for 医療費控除; medicine and follow-up reminders; CSV export and backup", "2,069 phrases (19 situations), 174 illness guides, 70 procedure and insurance articles, a 2,669-word medical dictionary, with furigana", "Free, non-profit, no ads, no account; Vietnamese, Japanese and English interface"]',
    seo_title = 'ViCare – See a Doctor in Japan, Free App for Vietnamese',
    seo_description = 'ViCare helps Vietnamese people see a doctor in Japan: a 3,700-sentence visit interpreter, health records, camera reading of medicine bags, 119 scripts. Free.'
WHERE locale = 'en'
  AND product_id = (SELECT id FROM products WHERE slug = 'vicare');

UPDATE product_translations
SET name = 'ViCare（日本での受診サポート）',
    tagline = '日本で病院にかかるベトナム人のための無料アプリ：診察時の通訳、健康記録、書類・薬袋の読み取り',
    description = 'ViCareはViMaiの無料・非営利アプリで、日本に住むベトナム人が体調を崩してから薬を受け取って帰るまでを支えます。診察時の通訳には、医師・スタッフ・患者の例文3,700文以上を、内科、小児科、産婦人科、眼科、耳鼻咽喉科、歯科、皮膚科、薬局、救急など診療科・場面別の20パックに収録し、端末の音声認識でマイクから聞き取ります。健康記録は端末内に保存され、日本語で表示する緊急医療情報、費用付きの受診記録と医療費控除のための年間合計、服用中の薬、服薬・再診のリマインダーを備えています。薬袋、予約票、領収書、検査結果、健康診断結果、問診票、同意書はカメラで撮ると端末内で読み取ります。「具合が悪い」では100の症状と58の危険なサインから受診する診療科の目安を示し、厚生労働省のオープンデータによる全国47都道府県・14万以上の医療機関の一覧も使えます。ほかに会話フレーズ2,069文、病気ガイド174件、手続き・保険の記事70本、医療用語辞典2,669語があります。アカウント不要で、個人のデータは端末内だけに保存されます。',
    long_description = '受診時のコミュニケーションを助ける参考情報のアプリで、診断ではなく、医師や薬剤師の助言に代わるものではありません。内容は日本の公的な医療情報をもとにViCareチームが作成・確認しています。アカウント不要、広告なしで、個人のデータは端末内だけに保存されます。',
    target_audience = '日本で病院・クリニックを受診するベトナム人と、その受診を支える家族、会社、学校、支援機関の方。',
    features = '["診察通訳：診療科・場面別20パック・3,700文以上の例文、マイクで聞き取り。患者はベトナム語で話すか入力し、医師は日本語で読める", "健康記録：日本語で表示する緊急医療情報（アレルギー、持病、血液型、連絡先）、受診記録、服用中の薬", "カメラで端末内読み取り：薬袋から服用スケジュール、予約票、領収書、検査・健診結果、問診票", "話した言葉をそのまま翻訳：例文にない発言も無料で端末内翻訳、初回に言語データをダウンロードすればオフラインでも利用可（「機械翻訳」と表示し、確認用の逆翻訳付き。iPhone/Androidアプリ）", "具合が悪い：100の症状・15の部位・58の危険なサインから診療科の目安", "医療機関を探す：厚生労働省のオープンデータによる47都道府県・14万以上の医療機関、20の診療科、Googleマップ検索も", "119・110・#7119・#8000の伝え方（保存した住所を自動入力）", "受診記録（医療機関・薬局の費用、医療費控除のための年間合計）、服薬・再診のリマインダー、CSV書き出し・バックアップ", "会話フレーズ2,069文（19場面）、病気ガイド174件、手続き・保険70本、医療用語辞典2,669語（振り仮名付き）", "無料・非営利、広告なし、アカウント不要。ベトナム語・日本語・英語の表示"]',
    seo_title = 'ViCare｜ベトナム人の日本での受診をサポートする無料アプリ',
    seo_description = 'ViCareは日本で病院にかかるベトナム人のための無料アプリ。3,700文以上の診察通訳、健康記録、薬袋のカメラ読み取り、診療科の案内、119番の伝え方。'
WHERE locale = 'ja'
  AND product_id = (SELECT id FROM products WHERE slug = 'vicare');
